function assignLetterGrade(score) {
  if (score < 0 || score > 100) {
    return "Invalid Score: Must be between 0 and 100";
  }

  if (score >= 90) {
    return "A";
  } else if (score >= 80) {
    return "B";
  } else if (score >= 70) {
    return "C";
  } else if (score >= 60) {
    return "D";
  } else {
    return "F";
  }
}

console.log(assignLetterGrade(94)); // A
console.log(assignLetterGrade(83)); // B
console.log(assignLetterGrade(52)); // F

function getAccessDescription(role) {
  let description = "";

  switch (role) {
    case "admin":
      description = "Full system read, write, and user deletion access.";
      break; // Critical: prevents fallthrough into subsequent cases!

    case "editor":
      description = "Content creation and publishing access.";
      break;

    case "subscriber":
    case "viewer": // Multi-case grouping
      description = "Read-only access to published articles.";
      break;

    default:
      description = "Unrecognized role: No permissions granted.";
      break;
  }

  return description;
}

console.log(getAccessDescription("editor"));
console.log(getAccessDescription("viewer"));

// 1. Standard 'for' loop (known iteration count)
console.log("--- FOR LOOP ---");
for (let i = 1; i <= 3; i++) {
  console.log(`Counter: ${i}`);
}

// 2. 'while' loop (checks condition BEFORE entering body)
console.log("--- WHILE LOOP ---");
let energy = 3;
while (energy > 0) {
  console.log(`Remaining energy: ${energy}`);
  energy--;
}

// 3. 'do-while' loop (evaluates condition AFTER executing body at least once)
console.log("--- DO-WHILE LOOP ---");
let attempts = 0;
do {
  console.log(`Executed attempt #${attempts}`);
  attempts++;
} while (attempts < 0); // Condition is false immediately, yet body executed once!
